      'Perdedor con moral de perdedor, [nombre]. Ni siquiera te indigna estar abajo.',
      '[nombre], eres de los que se apuntan a todo y no terminan nada. Y encima te ofende que se note.',
      'Tu mayor talento, [nombre], es encontrar razones por las que no era el momento.',
      '[nombre], perdedor con la seguridad de un campeón. Esa desconexión es lo más gracioso de ti.',
      'Eres tan mediocre, [nombre], que ni tus enemigos se molestan en mantenerse.',
      '[nombre], has fallado en tantas cosas distintas que ya es un dato biográfico, no un accidente.',
      'Perdedor sin plan B porque tampoco tenías plan A, [nombre].',
      '[nombre], la única constante en todos tus fracasos eres tú. Piénsalo con calma.',
      'Eres el tipo que llega tarde a su propia oportunidad, [nombre], y encima se queja del tráfico.',
      '[nombre], perdedor de esos que confunden la terquedad con el carácter.',
      'Tu presencia no suma, [nombre], y tu ausencia tampoco resta. Ese es el diagnóstico completo.',
      '[nombre], has hecho de la queja tu forma de participar. No cuenta como participar.',
      'Perdedor con reflejos lentos y ambiciones rápidas, [nombre]. Nunca se encuentran.',
      '[nombre], eres el que siempre estuvo cerca. Y estar cerca no aparece en ningún marcador.',
      'Eres un fracasado con estilo propio, [nombre]: el de fallar siempre por el mismo lado.',
      '[nombre], la gente no te subestima. Te estima exactamente en lo que vales, que es poco.',
      'Perdedor de esos que necesitan que alguien les diga que lo hicieron bien, [nombre]. Nadie lo ha dicho todavía.',
      '[nombre], tu vida entera es una demostración de que las ganas sin capacidad no llevan a ningún lado.',
      'Eres el error que se repite porque nadie se molesta en corregirlo, [nombre].',
      '[nombre], perdedor con memoria corta para lo suyo y larga para lo ajeno.',
      'Tienes el orgullo de alguien que ganó algo alguna vez, [nombre]. Nunca ganaste nada.',
      '[nombre], eres la razón por la que existe la expresión más vale no contar con él.',
      'Perdedor de manual, capítulo uno, párrafo uno, [nombre]. No hace falta seguir leyendo.',
      '[nombre], has convertido el casi en tu domicilio fiscal.',
      'Eres tan poca cosa, [nombre], que ni cuando fallas alguien se molesta en corregirte.',
      '[nombre], perdedor por acumulación. No fue un golpe, fueron doscientos golpecitos.',
      'Tu problema no es que no sepas, [nombre]. Es que crees que sabes.',
      '[nombre], eres de los que pierden y suben la voz. Como si el volumen cambiara el resultado.',
      'Perdedor sin narrativa, [nombre]. Ni tragedia, ni comedia. Solo un expediente gris.',
      '[nombre], nadie te ha puesto la zancadilla. Te caes solo, y con ganas.',
      'Eres el fracaso más previsible del grupo, [nombre], y aun así llegas tarde a él.',
      '[nombre], perdedor de esos que se enfadan con el espejo. El espejo no tiene la culpa.',
      'Llevas años preparándote para algo que ya pasó sin ti, [nombre].',
      '[nombre], eres la definición viva de esfuerzo mal invertido.',
      'Perdedor con recursos y sin resultados, [nombre]. Eso ya no tiene excusa.',
      '[nombre], has llegado al punto en que ni tú mismo te crees tus planes.',
      'Eres el único que no ve el patrón, [nombre]. Todos los demás lo tenemos claro desde hace tiempo.',
      '[nombre], perdedor sin escuela. Ni siquiera fracasas con técnica.',
      'Tu historial está tan cargado de derrotas, [nombre], que una victoria parecería un fallo de registro.',
      '[nombre], eres el que sobra en cualquier reparto. Y siempre te enteras el último.',
      'Perdedor con la energía de un ganador y la puntería de nadie, [nombre].',
      '[nombre], si tuvieras que resumir tu vida en una palabra, sería intento. En plural.',
      'Eres el peso muerto que todo grupo arrastra, [nombre]. Aquí te tocó a ti.',
      '[nombre], perdedor con opinión sobre todo y autoridad sobre nada.',
      'Nadie te ha cerrado ninguna puerta, [nombre]. Es que nunca llamaste.',
      '[nombre], eres tan constante en el fracaso que casi mereces un reconocimiento. Casi.',
      'Perdedor con la cara muy dura y el expediente muy blando, [nombre].',
      '[nombre], has fallado tantas veces que fallar dejó de doler y empezó a definirte.',
      'Eres el clásico que dice que se lo merecía otro, [nombre]. Efectivamente, se lo merecía otro.',
      '[nombre], perdedor sin herederos, sin discípulos y sin nadie que quiera tu puesto.',
      'Tu vida es una demostración práctica de lo que pasa cuando no eliges nunca, [nombre].',
      '[nombre], eres el que pide otra oportunidad justo después de gastar la última.',
      'Perdedor de esos que se conforman con no ser el último, [nombre]. Y a veces ni eso.',
      '[nombre], la gente ya no espera nada de ti, y eso es una forma muy educada de descartarte.',
      'Eres el fracaso que se normalizó, [nombre]. Ya ni se comenta, se asume.',
      '[nombre], perdedor con la estrategia de esperar a ver qué pasa. Nunca pasa nada bueno.',
      'Tienes todas las condiciones para perder, [nombre], y encima las cultivas.',
      '[nombre], eres el ejemplo de que la mediocridad también requiere dedicación.',
      'Perdedor completo, [nombre]: sin logros, sin plan, sin aliados y sin autocrítica.',
      '[nombre], has convertido tu vida en una sala de espera sin número.',
      'Eres tan poco, [nombre], que hasta el bot tiene que esforzarse para llenar la frase.',
      '[nombre], perdedor de los que insisten en el mismo error con distinta ropa.',
      'Nadie recuerda tu mejor momento, [nombre], porque nunca hubo uno que destacara sobre el resto.',
      '[nombre], eres la persona que aparece en el acta pero no en el partido.',
      'Perdedor con la ilusión intacta y la evidencia en contra, [nombre]. Elige un bando.',
      '[nombre], has perdido credibilidad, oportunidades y tiempo. En ese orden y por tu cuenta.',
      'Eres el que estropea lo que ya estaba hecho, [nombre]. Un talento muy específico.',
      '[nombre], perdedor sin remontada posible porque nunca hubo un punto de partida decente.',
      'Tu problema no es de suerte ni de contexto, [nombre]. Es estructural y viene de fábrica.',
      '[nombre], eres el nombre que se tacha primero cuando hay que reducir la lista.',
      'Perdedor con demasiada confianza y muy pocos datos que la sostengan, [nombre].',
      '[nombre], la única carrera en la que vas primero es la de las excusas.',
      'Eres el que se retira antes de que le echen, [nombre], y lo llama decisión propia.',
      '[nombre], perdedor de esos que hablan del futuro para no hablar del presente.',
      'Nada de lo que has empezado sigue en pie, [nombre]. Nada. Repásalo tú mismo.',
      '[nombre], eres el clásico caso de mucho movimiento y cero desplazamiento.',
      'Perdedor con la moral por los suelos y el ego por las nubes, [nombre]. Un desastre coherente.',
      '[nombre], has convertido tu incapacidad en una personalidad y encima la defiendes en público.',
      'Eres el que llega al final de todo, [nombre], cuando ya no queda nada que repartir.',
      '[nombre], perdedor de los que no dejan huella ni cuando pisan barro.',
      'Tu única victoria, [nombre], es que todavía no te han echado. Y eso también es cuestión de tiempo.',
